export function resolveLocale(...candidates: Array<string | undefined | null>): Locale {
  for (const candidate of candidates) {
    const normalized = (candidate || "").trim().toLowerCase().replace("_", "-");
    if (!normalized) continue;
    if (normalized.startsWith("zh")) return "zh-CN";
    if (normalized.startsWith("pt")) return "pt-BR";
    const matched = SUPPORTED_LOCALES.find((locale) => locale.toLowerCase() === normalized || normalized.startsWith(`${locale.toLowerCase()}-`));
    if (matched) return matched;
  }
  return "en";
}

export function initialLocale(telegramLanguage?: string): Locale {
  let saved = "";
  try { saved = localeStorage()?.getItem("aurax_locale") || ""; } catch { /* storage may be disabled */ }
  let requested = "";
  try {
    const candidate = new URLSearchParams(location.search).get("lang") || "";
    const normalized = candidate.trim().toLowerCase().replace("_", "-");
    const supported = normalized.startsWith("zh") || normalized.startsWith("pt") || SUPPORTED_LOCALES.some((locale) => normalized === locale.toLowerCase() || normalized.startsWith(`${locale.toLowerCase()}-`));
    if (supported) requested = resolveLocale(candidate);
  } catch { /* location may be unavailable during tests */ }
  if (requested) saveLocale(requested as Locale);
  return resolveLocale(requested, saved, telegramLanguage, ...navigator.languages, navigator.language);
}

export function saveLocale(locale: Locale) {
  try { localeStorage()?.setItem("aurax_locale", locale); } catch { /* storage may be disabled */ }
}

function localeStorage() {
  return (globalThis as typeof globalThis & { localStorage?: { getItem(key: string): string | null; setItem(key: string, value: string): void } }).localStorage;
}

export function isRtl(locale: Locale) {
  return locale === "ar" || locale === "fa";
}

export function translate(locale: Locale, key: TranslationKey, variables: Record<string, string | number> = {}) {
  const lookup = (candidate: Locale) => reliabilityDictionaries[candidate]?.[key]
    || errorDictionaries[candidate]?.[key]
    || subscriptionDictionaries[candidate]?.[key]
    || jobFilterDictionaries[candidate]?.[key]
    || jobActionDictionaries[candidate]?.[key]
    || jobDetailDictionaries[candidate]?.[key]
    || aspectRatioDictionaries[candidate]?.[key]
    || templateDictionaries[candidate]?.[key]
    || personaDictionaries[candidate]?.[key]
    || feedDictionaries[candidate]?.[key]
    || dictionaries[candidate]?.[key];
  const template = lookup(locale) || (CIS_RUSSIAN_FALLBACK_LOCALES.has(locale) ? lookup("ru") : undefined) || en[key];
  return template.replace(/\{\{(\w+)\}\}/g, (_match, name: string) => String(variables[name] ?? ""));
}
